return await (async () => {
  const api = globalThis.dnd5eClasspack;
  if (!api?.teleport) return ui.notifications.warn("请先启用 ClassPack。");
  const caster = canvas.tokens.controlled[0] ?? (typeof token === "undefined" ? null : token);
  if (!caster) return ui.notifications.warn("请先控制施法者的 Token。");
  let targets = Array.from(game.user.targets ?? []);
  if (!targets.length) targets = [...canvas.tokens.controlled];
  targets = targets.filter(target => target.id !== caster.id);
  if (!targets.length) return ui.notifications.warn("请选择要传送的目标，目标不能包含施法者。");
  let mode = "per-target";
  if (targets.length > 1) {
    mode = await api.dialogUtils.selectDialog("传送模式", "", {
      label: "落点", name: "mode", options: { options: [
        { value: "per-target", label: "为每个目标分别选择落点" },
        { value: "same-for-all", label: "为所有目标选择同一落点" }
      ] }
    });
    if (!mode) return;
  }
  const options = { centerpoint: caster, range: 30, timeout: 20000,
    avoidOccupied: true, animate: false, preserveOffsets: false };
  ui.notifications.info("选择 30 英尺范围内的落点；右键或 Esc 取消。");
  if (mode === "same-for-all") return api.teleport(targets, null, options);
  for (const target of targets) {
    const result = await api.teleport(target, null, options);
    if (result?.cancelled) break;
  }
})();
